/* ---------- Joker & Sterne: Einführung, Flug zum Chip, Regen */
function chipFly(sel, sym, txt) {
  var c = $(sel); if (!c) return; var r = c.getBoundingClientRect(), el = document.createElement('div'); el.className = 'flysym'; el.textContent = sym; el.style.left = (window.innerWidth / 2 - 30) + 'px'; el.style.top = (window.innerHeight / 2 - 30) + 'px'; document.body.appendChild(el);
  requestAnimationFrame(function () { el.style.transform = 'translate(' + (r.left + r.width / 2 - window.innerWidth / 2) + 'px,' + (r.top + r.height / 2 - window.innerHeight / 2) + 'px) scale(.35)'; el.style.opacity = '.9'; });
  setTimeout(function () { el.remove(); var c2 = $(sel); if (!c2) return; c2.classList.add('chipbump'); var b = document.createElement('span'); b.className = 'chipplus'; b.textContent = txt || '+1'; c2.appendChild(b); setTimeout(function () { c2.classList.remove('chipbump'); b.remove(); }, 2600); }, 1100);
}
var PILE = [];
function symRain(sym) {
  document.body.classList.add('shake'); setTimeout(function () { document.body.classList.remove('shake'); }, 650);
  var cx = window.innerWidth / 2, cy = window.innerHeight * 0.55;
  for (var i = 0; i < 46; i++) (function (i) {
    var el = document.createElement('div'); el.className = 'rainsym'; el.textContent = sym; var sz = 16 + Math.random() * 22; el.style.fontSize = sz + 'px'; el.style.left = cx + 'px'; el.style.top = cy + 'px'; document.body.appendChild(el); PILE.push(el);
    var ang = -Math.PI / 2 + (Math.random() - 0.5) * 2.4, sp = 9 + Math.random() * 13, vx = Math.cos(ang) * sp, vy = Math.sin(ang) * sp, x = cx, y = cy, rot = Math.random() * 360, vr = (Math.random() - 0.5) * 8, t = 0, sway = Math.random() * 6, phase = Math.random() * 6, ground = window.innerHeight - sz - Math.random() * 14;
    (function step() { t++; if (vy < 0 || t < 30) { vx *= 0.985; vy += 0.42; } else { vy = Math.min(vy + 0.05, 1.2 + Math.random() * 0.4); vx = Math.sin(t / 22 + phase) * (0.6 + sway * 0.15); } x += vx; y += vy; rot += vr * (vy > 1.5 ? 1 : 0.4); if (y >= ground) { y = ground; el.style.transform = 'translate(' + (x - cx) + 'px,' + (y - cy) + 'px) rotate(' + rot + 'deg)'; return; } el.style.transform = 'translate(' + (x - cx) + 'px,' + (y - cy) + 'px) rotate(' + rot + 'deg)'; requestAnimationFrame(step); })();
  })(i);
}
function pileClear() { PILE.forEach(function (e) { e.style.transition = 'opacity .8s'; e.style.opacity = 0; setTimeout(function () { e.remove(); }, 900); }); PILE = []; }
var LASTJ = null, LASTS = null, SKIPRAIN = 0;
function symWatch() { if (!V) return; var j = V.jokers || 0, s2 = V.hsPts || 0; if (LASTJ != null && j > LASTJ && !(SKIPRAIN & 1)) { try { SND.joker(); } catch (e) {} symRain('🃏'); } if (LASTS != null && s2 > LASTS && !(SKIPRAIN & 2)) { try { SND.level(); } catch (e) {} symRain('⭐'); } SKIPRAIN = 0; LASTJ = j; LASTS = s2; }
function jokIntroPop() {
  pop('<div style="text-align:center"><div class="introcard jk">🃏</div><h2 style="padding:0">Der Joker</h2><div class="small" style="line-height:1.65;text-align:left;max-width:440px;margin:0 auto">Vor deinem ersten Pokalspiel ein kleines Geschenk: <b>ein Joker</b>.<br><br>🔄 <b>Was er kann:</b> Direkt nach einem Spiel (zurück in der Übersicht) drehst du mit ihm die Zeit bis vor das Spiel zurück – alles wird zurückgesetzt und du kannst es nochmal versuchen. 1 Joker = 1 Wiederholung.<br>📣 <b>Wie du weitere bekommst:</b> viel Social Media, Kidsday, Fan-Tag und Fan-Aktionen – mit etwas Glück höchstens einer pro Saison.</div><button class="pri" style="width:100%;margin-top:14px" onclick="jokIntroOk()">Joker einsammeln</button></div>', { lock: true, nav: true });
}
function jokIntroOk() { SKIPRAIN |= 1; closePop(); act('jokIntroOk', {}, { quiet: true }); setTimeout(function () { try { SND.joker(); } catch (e) {} chipFly('.jokchip', '🃏', '+1'); }, 120); }
function starIntroPop() {
  pop('<div style="text-align:center"><div class="introcard st">⭐</div><h2 style="padding:0">Ein halber Stern!</h2><div class="small" style="line-height:1.65;text-align:left;max-width:440px;margin:0 auto">Glückwunsch zum ersten Sieg! Dafür gibt es <b>½ Stern</b>.<br><br>⭐ <b>Was du damit machst:</b> Am Saisonende verteilst du halbe Sterne an deine Spieler – jeder bekommt dadurch mehr Talent und entwickelt sich schneller (½ Stern pro Spieler und Saison).<br>🏆 <b>Wie du mehr bekommst:</b> Meisterschaft, Aufstieg, Pokalsiege und besondere Erfolge.</div><button class="pri" style="width:100%;margin-top:14px" onclick="starIntroOk()">Stern einsammeln</button></div>', { lock: true, nav: true });
}
function starIntroOk() { SKIPRAIN |= 2; closePop(); act('starIntroOk', {}, { quiet: true }); setTimeout(function () { try { SND.level(); } catch (e) {} chipFly('.stchip', '⭐', '+½'); }, 120); }

/* ---------- Tägliche Login-Belohnung (7 Tage) */
function dailyKick() { if (!S || !MGR) return Promise.resolve(); return serverAct('dailyCheck', {}).then(function () { V = MGR.view(S, D); }, function () { }); }
function dailyPop() {
  var Dl = V.daily; if (!Dl) return; var n = Dl.streak;
  var tiles = [1, 2, 3, 4, 5, 6, 7].map(function (i) { var past = i < n, cur = i === n, main = i === 7; return '<div class="dtile' + (past ? ' done' : '') + (cur ? ' cur' : '') + (main ? ' main' : '') + '"' + (cur ? ' onclick="dailyTake(this)"' : '') + '><small>Tag ' + i + '</small><div class="dic">' + (past ? '✖' : cur ? (main ? '🏆' : '🎁') : main ? '🏆' : '❔') + '</div>' + (cur ? '<b>Antippen!</b>' : past ? '<span>abgeholt</span>' : '<span>' + (main ? 'Hauptpreis' : '???') + '</span>') + '</div>'; }).join('');
  pop('<div style="text-align:center"><h2 style="padding:0">🎁 Tägliche Belohnung</h2><div class="small muted" style="margin-bottom:12px">Jeden Tag einloggen – an Tag 7 wartet der Hauptpreis. Verpasst du einen Tag, geht es wieder bei Tag 1 los.</div><div class="dgrid">' + tiles + '</div></div>', { lock: true, wide: true, nav: true });
}
function dailyTake(el) {
  el.onclick = null;
  serverAct('dailyClaim', {}).then(function () { dailyShow(el); }, function (e) { toast(String((e && e.message) || e), true); });
}
function dailyShow(el) {
  V = MGR.view(S, D); var pz = V.dailyLast || {}; el.classList.add('reveal'); el.onclick = null; el.querySelector('.dic').textContent = pz.ic || '🎁'; el.querySelector('b').textContent = pz.txt || '';
  try { SND.coin(); } catch (e) {}
  setTimeout(function () { closePop(); render(); setTimeout(function () { var tg = pz.t === 'joker' ? '.jokchip' : pz.t === 'star' ? '.stchip' : pz.t === 'club' ? '.kpi.fin' : pz.t === 'xp' ? '.lvbox' : pz.t === 'priv' ? '#tabs button[data-g="managerG"]' : '#tabs button[data-g="home"]'; SKIPRAIN |= 3; chipFly(tg, pz.ic || '🎁', pz.t === 'joker' ? '+1' : pz.t === 'star' ? '+½' : '+'); }, 150); }, 1300);
}

setInterval(function () { try { if (ST.screen === 'start' && !document.querySelector('#pop')) startScreen(); SAL.at = 0; if ($('#salrk')) loadSalary(true); } catch (e) {} }, 3600000);

boot();
